	address internal immutable routesData;
	uint256 internal immutable numImplementations;
	uint256 internal immutable numSigs;
	address internal immutable fallbackImplementation;

	/// @param routes define the routing (see `Routes`)
	constructor(Routes memory routes) {
		RouterRoutes.check(routes);
		uint256 tmpNumImplementations = routes.implementations.length;
		uint256 tmpNumSigs = routes.sigMap.length;
		uint256 dataSize = 1 + tmpNumImplementations * 20 + tmpNumSigs * 5;
