pragma solidity ^0.8.0;

/// @notice The routes a router is constructed with (the same shape as Router10X60's).
/// @param implementations the implementations' addresses, at most 256
/// @param sigMap one entry per selector, 5 bytes: the selector (the upper 4 bytes) then the index
///  of its implementation in `implementations` (the lowest byte); strictly increasing, so sorted
///  and without a selector twice, so a router can binary-search it
/// @param fallbackImplementation where any other selector goes (zero for none: such a call then
///  reverts UNKNOWN_METHOD)
struct Routes {
	address[] implementations;
	bytes5[] sigMap;
	address fallbackImplementation;
}

/// @title What `Router` and `InlineRouter` share: the checks of their routes, and their packing
/// @author Ronan Sandford
library RouterRoutes {
	/// @notice Reverts unless the routes can be served: at most 256 implementations, at least one
	///  implementation or a fallback, every implementation and the fallback holding code (a
	///  delegatecall to an address without code succeeds and does nothing), the sig map strictly
	///  increasing and every index pointing at an implementation.
	function check(Routes memory routes) internal view {
		uint256 numImplementations = routes.implementations.length;
		uint256 numSigs = routes.sigMap.length;
		require(numImplementations <= 256, 'MAX_IMPLEMENTATIONS_REACHED');
		require(numImplementations > 0 || routes.fallbackImplementation != address(0), 'NO_ROUTES');

		for (uint256 i = 0; i < numImplementations; i++) {
			require(routes.implementations[i].code.length > 0, 'IMPLEMENTATION_WITHOUT_CODE');
		}
		if (routes.fallbackImplementation != address(0)) {
			require(routes.fallbackImplementation.code.length > 0, 'IMPLEMENTATION_WITHOUT_CODE');
		}

		uint256 previous;
		for (uint256 i = 0; i < numSigs; i++) {
			uint40 entry = uint40(routes.sigMap[i]);
			uint256 sig = entry >> 8;
			require(i == 0 || sig > previous, 'SIGS_NOT_SORTED');
			require((entry & 0xFF) < numImplementations, 'INVALID_IMPLEMENTATION_INDEX');
			previous = sig;
		}
	}

	/// @notice Writes the implementations (20 bytes each) then the sig map (5 bytes an entry),
	///  packed, at `out`, and returns the address just past them. The caller owns at least 32
	///  bytes of memory past the end (each write is a full word).
	function pack(Routes memory routes, uint256 out) internal pure returns (uint256 end) {
		address[] memory implementations = routes.implementations;
		bytes5[] memory sigMap = routes.sigMap;
		assembly {
			let p := out
			let numImplementations := mload(implementations)
			for {
				let i := 0
			} lt(i, numImplementations) {
				i := add(i, 1)
			} {
				mstore(p, shl(96, mload(add(implementations, mul(add(i, 1), 32)))))
				p := add(p, 20)
			}
			let numSigs := mload(sigMap)
			for {
				let i := 0
			} lt(i, numSigs) {
				i := add(i, 1)
			} {
				// a bytes5 in memory is left-aligned in its word
				mstore(p, mload(add(sigMap, mul(add(i, 1), 32))))
				p := add(p, 5)
			}
			end := p
		}
	}
}
